<section class="card allocation-connect"><div class="section-heading"><div><p class="eyebrow"><?= e(t('CONNECT YOUR PLAN TO REAL MONEY')) ?></p><h2><?= e(t('Give your next salary a destination.')) ?></h2></div><span class="badge"><?= e(t('Only future income')) ?></span></div><p class="muted"><?= e(t('Use this plan’s starting savings rate of')) ?> <?= e(number_format($plan['savings_percent'],2)) ?><?= e(t('% and investment rate of')) ?> <?= e(number_format($plan['investment_percent'],2)) ?><?= e(t('% for new manual or recurring income. Your investment share becomes a deposit in the asset you choose.')) ?></p>
<form class="form-grid" method="post" action="/salary/plan/allocations" data-confirm="<?= e(t('Replace the current income allocation rules with this plan’s starting rates? Existing income will keep its original split.')) ?>"><?= csrf_field() ?><input type="hidden" name="month" value="<?= e($month) ?>"><label><?= e(t('Living & bills account')) ?><select name="spending_account_id" required><?php foreach ($allocationAccounts as $account): ?><option value="<?= e($account['id']) ?>"><?= e($account['name']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Savings account')) ?><select name="savings_account_id" <?= $plan['savings_percent']>0 ? 'required' : '' ?>><option value=""><?= e(t('Choose an account')) ?></option><?php foreach ($allocationSavingsAccounts as $account): ?><option value="<?= e($account['id']) ?>"><?= e($account['name']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Investment asset')) ?><select name="investment_asset_id" <?= $plan['investment_percent']>0 ? 'required' : '' ?>><option value=""><?= e(t('Choose an investment')) ?></option><?php foreach ($allocationAssets as $asset): ?><option value="<?= e($asset['id']) ?>"><?= e($asset['name']) ?></option><?php endforeach; ?></select></label><div><button><?= e(t('Use these allocation rules')) ?></button></div></form>
<p class="footnote"><?= e(t('This replaces the current allocation rules and moves no money immediately.')) ?> <a href="/investments"><?= e(t('Add an investment asset')) ?></a> <?= e(t('if your list is empty. Record salary in')) ?> <a href="/salary"><?= e(t('Money')) ?></a><?= e(t(', or set up')) ?> <a href="/salary/recurring"><?= e(t('recurring income')) ?></a><?= e(t(', to create actual savings and investment deposits. Review the suggested step-up each month before changing your rules.')) ?></p></section>
